// Electron layout probe for the CURRENT float page (generated by prepare.mjs).
// Measures real layout at 300x175, requests the same fit the host would apply,
// then re-measures after the resize and captures PNGs.
const { app, BrowserWindow } = require('electron');
const path = require('path');
const fs = require('fs');

app.disableHardwareAcceleration();

const CASES = [
  { name: 'working', shot: true, set: { mode: 'working', taskText: 'Refactor plan analysis', currentSessionId: 's1' } },
  { name: 'waiting-approval', shot: true, set: { mode: 'waiting', kind: 'approval', taskText: 'cleanup', currentSessionId: 's1', pending: { kind: 'approval', sessionId: 's1', summary: 'Run rm -rf /tmp/x' } } },
  { name: 'waiting-question', shot: true, set: { mode: 'waiting', kind: 'question', taskText: 'Which DB?', currentSessionId: 's1', pending: { kind: 'question', sessionId: 's1', questionId: 'q1', summary: 'Which database?', multi: false, options: [{ label: 'Postgres', description: 'relational', recommended: true }, { label: 'MySQL', description: '', recommended: false }] } } },
  { name: 'done', shot: true, set: { mode: 'done', taskText: 'Build passed', currentSessionId: 's1' } },
  { name: 'greeting', shot: false, set: { mode: 'idle', greetUntil: Date.now() + 6000 } },
  { name: 'appearance-0.6-1.3', shot: true, scale: 1.3, alpha: 0.6, set: { mode: 'waiting', kind: 'approval', taskText: 'cleanup', currentSessionId: 's1', pending: { kind: 'approval', sessionId: 's1', summary: 'Run rm -rf /tmp/x' } } },
];

const SNAP = `(async (cfg) => {
  window.__reset();
  for (const [k, v] of Object.entries(cfg.set)) window[k] = v;
  if (cfg.scale) window.applyLayerScale(cfg.scale);
  if (cfg.alpha) window.applyLayerAlpha(cfg.alpha);
  window.render();
  await new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r)));
  const rect = (el) => { const r = el.getBoundingClientRect(); return { x: +r.x.toFixed(1), y: +r.y.toFixed(1), w: +r.width.toFixed(1), h: +r.height.toFixed(1) }; };
  const sels = ['.bubble.status', '.bubble.alert', '.bubble.greet', '.bubble.act'];
  const pet = document.getElementById('pet');
  const cs = (el) => getComputedStyle(el);
  const pseudo = (sel) => { const p = getComputedStyle(document.querySelector(sel), '::before'); return { content: p.content, width: p.width, height: p.height }; };
  return {
    anim: window.currentAnim,
    inner: { w: window.innerWidth, h: window.innerHeight },
    pet: { rect: rect(pet), offset: { w: pet.offsetWidth, h: pet.offsetHeight }, opacity: cs(pet).opacity, transform: cs(pet).transform },
    bubbles: sels.map((sel) => {
      const el = document.querySelector(sel);
      return { sel, display: el.style.display || '(default)', rect: rect(el), offset: { w: el.offsetWidth, h: el.offsetHeight }, scroll: { w: el.scrollWidth, h: el.scrollHeight }, opacity: cs(el).opacity };
    }),
    fit: window.__calls.filter((c) => c[0] === 'fitContent').slice(-1)[0] || null,
    pseudo: { status: pseudo('.bubble.status'), alert: pseudo('.bubble.alert') },
    vars: {
      alpha: document.documentElement.style.getPropertyValue('--pet-alpha'),
      bubbleAlpha: document.documentElement.style.getPropertyValue('--bubble-alpha'),
      scale: document.documentElement.style.getPropertyValue('--pet-scale'),
    },
  };
})`;

app.whenReady().then(async () => {
  const win = new BrowserWindow({
    width: 300,
    height: 175,
    show: false,
    frame: false,
    transparent: true,
    webPreferences: { offscreen: true, contextIsolation: false, nodeIntegration: false },
  });
  await win.loadFile(path.join(__dirname, 'index.html'));
  await win.webContents.insertCSS('* { transition: none !important; }');
  const wait = (ms) => new Promise((r) => setTimeout(r, ms));
  await wait(300);

  const out = { css: await win.webContents.executeJavaScript(`(() => {
    const el = document.querySelector('.bubble.alert');
    const cs = getComputedStyle(el);
    let rules = -1;
    try { rules = document.styleSheets[0].cssRules.length; } catch (e) { rules = 'ERR:' + e.name; }
    return { alertAnimation: cs.animationName, ruleCount: rules };
  })()`), cases: {} };

  for (const c of CASES) {
    const snap = await win.webContents.executeJavaScript(
      `${SNAP}(${JSON.stringify({ scale: c.scale || null, alpha: c.alpha || null, set: c.set })})`,
      true,
    );
    if (snap.fit) {
      const [, fw, fh] = snap.fit;
      win.setBounds({ x: 0, y: 0, width: Math.max(220, Math.min(560, fw)), height: Math.max(160, Math.min(720, fh)) });
      await wait(120);
      snap.afterResize = await win.webContents.executeJavaScript(
        `${SNAP}(${JSON.stringify({ scale: c.scale || null, alpha: c.alpha || null, set: c.set })})`, true);
      if (c.shot) {
        const img2 = await win.webContents.capturePage();
        fs.writeFileSync(path.join(__dirname, `shot-${c.name}-fit.png`), img2.toPNG());
      }
    }
    out.cases[c.name] = snap;
    if (c.shot) {
      const img = await win.webContents.capturePage();
      fs.writeFileSync(path.join(__dirname, `shot-${c.name}.png`), img.toPNG());
    }
  }
  console.log(JSON.stringify(out, null, 2));
  win.destroy();
  app.quit();
});
